@-moz-document domain("rptl.us") {
/* Targets any img element where the source ends with or contains anger.png */
    img[src*="anger.png"] {
        content: url("https://imgur.com/a/lkw74J1") !important;
        
        /* Optional: Ensures your custom image scales correctly if it is a different size */
        object-fit: contain; 
    }
}
